#include "cartmesh2d/grid/RectilinearMesh2D.hpp"
#include "cartmesh2d/io/MeshIO2D.hpp"
#include "cartmesh2d/quality/SolverQuality2D.hpp"
#include <algorithm>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <map>
#include <set>
#include <sstream>
#include <stdexcept>
#include <vector>

using namespace cartmesh2d;

static std::string cellKey(const TopologyMesh2D& t, const TopologyCell2D& c) {
    std::vector<std::pair<double,double>> p;
    for (auto id : c.vertices) p.push_back({t.vertices.at(id).point.x,t.vertices.at(id).point.y});
    std::sort(p.begin(),p.end());
    std::ostringstream out; out << std::hexfloat;
    for (auto [x,y] : p) out << x << ',' << y << ';';
    return out.str();
}

int main(int argc, char** argv) {
    try {
        if (argc != 3) throw std::runtime_error("usage: generate_top_domain original.cm2d output-prefix");
        const auto originalRead = readCm2dTopology(argv[1]);
        if (!originalRead.valid()) throw std::runtime_error(originalRead.error);
        const auto& original = originalRead.topology;
        std::vector<double> x,y;
        for (const auto& v : original.vertices) { x.push_back(v.point.x); y.push_back(v.point.y); }
        auto uniqueSorted=[](std::vector<double>& a){
            std::sort(a.begin(),a.end()); a.erase(std::unique(a.begin(),a.end()),a.end());
        };
        uniqueSorted(x); uniqueSorted(y);
        if (x.size()!=401 || y.size()!=33 || y.front()!=0.0 || y.back()!=1.0)
            throw std::runtime_error("unexpected baseline coordinate counts or bounds");
        y.push_back(1.25); y.push_back(1.5); y.push_back(1.75); y.push_back(2.0);
        const auto extended=makeRectilinearMesh2D(x,y);
        if (extended.cells.size()!=14400) throw std::runtime_error("unexpected extended cell count");
        std::map<std::string,std::size_t> lowerOriginal,lowerExtended;
        for (const auto& c : original.cells) {
            bool lower=true; for (auto id:c.vertices) lower &= original.vertices.at(id).point.y<=1.0;
            if (!lower) throw std::runtime_error("baseline has cell above y=1");
            ++lowerOriginal[cellKey(original,c)];
        }
        for (const auto& c : extended.cells) {
            bool lower=true; for (auto id:c.vertices) lower &= extended.vertices.at(id).point.y<=1.0;
            if (lower) ++lowerExtended[cellKey(extended,c)];
        }
        if (lowerOriginal != lowerExtended) throw std::runtime_error("lower cell polygon set mismatch");
        const auto originalQ=evaluateSolverQuality2D(original), extendedQ=evaluateSolverQuality2D(extended);
        if (!originalQ.valid() || !extendedQ.valid()) throw std::runtime_error("Solver quality gate failed");
        std::string error; const std::string prefix=argv[2];
        if (!writeCm2dTopology(extended,prefix+".cm2d",&error) || !writeLegacyVtk2D(extended,prefix+".vtk",&error)) throw std::runtime_error(error);
        std::ofstream q(prefix+".quality.json"); q << solverQualityReportToJson(extendedQ);
        std::ofstream report(prefix+".geometry.json");
        report << std::setprecision(17) << "{\"baselineCells\":" << original.cells.size()
               << ",\"extendedCells\":" << extended.cells.size() << ",\"baselineXCount\":" << x.size()
               << ",\"baselineYCount\":33,\"extendedYCount\":" << y.size()
               << ",\"lowerBaselineCells\":" << lowerOriginal.size() << ",\"lowerExtendedCells\":" << lowerExtended.size()
               << ",\"lowerCellPolygonSetIdentical\":true,\"baselineQualityValid\":true,\"extendedQualityValid\":true"
               << ",\"extendedYTop\":2}\n";
        std::cout << "baselineCells=" << original.cells.size() << " extendedCells=" << extended.cells.size()
                  << " x=" << x.size() << " y=" << y.size() << " lowerCells=" << lowerExtended.size() << '\n';
        return 0;
    } catch (const std::exception& e) { std::cerr << e.what() << '\n'; return 1; }
}
